    fn exec_dispatch_local_inductive(pre: Self, post: Self, node_id: NodeId) {
        // Extract variables from the pre-state Loop combiner
        let queued_ops = pre.combiner[node_id].get_Loop_queued_ops();
        let lversion = pre.combiner[node_id].get_Loop_lversion();
        let tail = pre.combiner[node_id].get_Loop_tail();
        let idx = pre.combiner[node_id].get_Loop_idx();
        let rid = queued_ops[idx as int];
        let log_entry = pre.log[lversion];
        let old_nr_state = pre.replicas[node_id];
        let (new_nr_state, ret) = DT::dispatch_mut_spec(old_nr_state, log_entry.op);

        // From transition requires
        assert(lversion < tail);
        assert(log_entry.node_id == node_id);

        // From pre invariant
        assert(pre.wf_combiner_for_node_id(node_id));

        // Unpack the LogRangeMatchesQueue at lversion (local node entry)
        // This extracts: idx < queued_ops.len(), pre.local_updates[rid].is_Placed(),
        // pre.local_updates[rid].get_Placed_idx() == lversion,
        // and LogRangeMatchesQueue(queued_ops, pre.log, idx+1, lversion+1, tail, node_id, pre.local_updates)
        LogRangeMatchesQueue_unpack_local_step(
            queued_ops, pre.log, idx, lversion, tail, node_id, pre.local_updates
        );

        // Prove the precondition for LogRangeMatchesQueue_update_change:
        // For rid: its Placed idx = lversion, which is below the range [lversion+1, tail)
        // For all other r: post.local_updates[r] == pre.local_updates[r]
        assert(forall|r: ReqId| #[trigger] pre.local_updates.contains_key(r) ==>
            pre.local_updates[r].is_Placed() && (lversion + 1) as nat <= pre.local_updates[r].get_Placed_idx() < tail ==>
            post.local_updates.contains_key(r) && post.local_updates[r] === pre.local_updates[r]
        ) by {
            assert forall|r: ReqId|
                #[trigger] pre.local_updates.contains_key(r) &&
                pre.local_updates[r].is_Placed() &&
                (lversion + 1) as nat <= pre.local_updates[r].get_Placed_idx() < tail
                implies post.local_updates.contains_key(r) && post.local_updates[r] === pre.local_updates[r]
            by {
                if r == rid {
                    // rid's Placed idx = lversion, not >= lversion+1 => contradiction
                    assert(pre.local_updates[rid].get_Placed_idx() == lversion);
                    assert(false);
                }
                // r != rid: post.local_updates[r] = pre.local_updates[r] unchanged
            };
        };

        // Convert LogRangeMatchesQueue from pre.local_updates to post.local_updates
        LogRangeMatchesQueue_update_change(
            queued_ops, pre.log, (idx + 1) as nat, (lversion + 1) as nat, tail, node_id,
            pre.local_updates, post.local_updates
        );

        // Prove QueueRidsUpdateDone for idx+1
        assert(QueueRidsUpdateDone(queued_ops, post.local_updates, (idx + 1) as nat)) by {
            assert forall|j: int| 0 <= j < (idx + 1) as nat =>
                post.local_updates.contains_key(#[trigger] queued_ops[j]) =>
                (post.local_updates[queued_ops[j]].is_Applied() || post.local_updates[queued_ops[j]].is_Done())
            by {
                if j < idx as int {
                    // From pre QueueRidsUpdateDone, queued_ops[j] != rid by seq_unique
                    assert(queued_ops[j] != rid) by {
                        assert(seq_unique(queued_ops));
                        assert(j != idx as int);
                        assert(0 <= idx as int < queued_ops.len() as int);
                        assert(0 <= j < queued_ops.len() as int);
                    };
                    assert(post.local_updates[queued_ops[j]] === pre.local_updates[queued_ops[j]]);
                } else {
                    // j == idx
                    assert(j == idx as int);
                    assert(queued_ops[j] == rid);
                    assert(post.local_updates[rid] === (UpdateState::Applied { ret, idx: lversion }));
                    assert(post.local_updates[queued_ops[j]].is_Applied());
                }
            }
        };

        // Prove QueueRidsUpdatePlaced for idx+1
        assert(QueueRidsUpdatePlaced(queued_ops, post.local_updates, (idx + 1) as nat)) by {
            assert forall|j: int| (idx + 1) as nat <= j < queued_ops.len() =>
                (post.local_updates.contains_key(#[trigger] queued_ops[j]) &&
                 post.local_updates[queued_ops[j]].is_Placed())
            by {
                // From pre QueueRidsUpdatePlaced(queued_ops, pre.local_updates, idx),
                // queued_ops[j] != rid by seq_unique (j > idx)
                assert(queued_ops[j] != rid) by {
                    assert(seq_unique(queued_ops));
                    assert(j != idx as int);
                    assert(0 <= idx as int < queued_ops.len() as int);
                };
