                            if post.local_updates.contains_key(qops[j]) {
                                assert(qops[j] != rid) by {
                                    if qops[j] == rid {
                                        assert(nid_qops.contains(rid));
                                        assert(false);
                                    }
                                };
                                assert(post.local_updates[qops[j]] === pre.local_updates[qops[j]]);
                            }
                        };
                    };
                }
            }

            assert(post.wf_combiner_for_node_id(nid));
        }
    };
